535	// migrateLoopState holds the mutable bookkeeping carried across iterations of
536	// migrateCheckpointsV2's main loop. Helpers hang off it so the loop body
537	// stays small enough to satisfy the maintainability-index lint.
538	type migrateLoopState struct {
539		pendingFull    []migratedFullCheckpoint
540		pendingMain    []checkpoint.WriteCommittedOptions
541		writtenRefs    []plumbing.ReferenceName
542		nextGeneration int
543		batchSize      int
544	
