548	func newMigrateLoopState(batchSize int) *migrateLoopState {
549		return &migrateLoopState{
550			pendingFull:    make([]migratedFullCheckpoint, 0, batchSize),
551			pendingMain:    make([]checkpoint.WriteCommittedOptions, 0, batchSize),
552			batchSize:      batchSize,
553			compactOffsets: newMigrateCompactOffsetCache(),
554		}
555	}
556	
557	// flushMain pushes any buffered /main entries through WriteCommittedMainBatch.
558	func (s *migrateLoopState) flushMain(ctx context.Context, v2Store *checkpoint.V2GitStore) error {
559		if len(s.pendingMain) == 0 {
560			return nil
561		}
562		if err := v2Store.WriteCommittedMainBatch(ctx, s.pendingMain); err != nil {
