232	// dryRunCheckpointsV2 inspects v1 vs v2 stores and prints a report. Returns
233	// (pendingCount, totalV1, error). The pending set is the same as the trigger
234	// for the post-push migration hint: any v1 checkpoint ID absent from v2's
235	// /main ref. Output goes to `out`; nothing is written to either store.
236	func dryRunCheckpointsV2(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, repoRoot string, out io.Writer) (int, int, error) {
237		v1List, err := v1Store.ListCommitted(ctx)
238		if err != nil {
239			return 0, 0, fmt.Errorf("failed to list v1 checkpoints: %w", err)
240		}
241		if len(v1List) == 0 {
242			fmt.Fprintln(out, "No v1 checkpoints found.")
243			return 0, 0, nil
244		}
