255		pending := make([]checkpoint.CommittedInfo, 0)
256		for _, info := range v1List {
257			if _, ok := v2Set[info.CheckpointID.String()]; !ok {
258				pending = append(pending, info)
259			}
260		}
261	
262		if len(pending) == 0 {
263			fmt.Fprintf(out, "All %d v1 checkpoints are already in v2. Nothing to migrate.\n", len(v1List))
